from fastmcp import FastMCP, Message, PromptResult, prompt

@prompt("summarize")
def summarize_prompt(text: str) -> PromptResult:
    """Prompt template for summarizing text."""
    return PromptResult(
        messages=[
            Message(f"Please summarize the following text:\n\n{text}")
        ]
    )

if __name__ == "__main__":
    server = FastMCP("Summarize Server")
    server.add_prompt(summarize_prompt)
